    readonly TextBox password = new() { PlaceholderText = "Mot de passe", Width = 280, UseSystemPasswordChar = true };
    readonly Label message = new() { AutoSize = true, ForeColor = Color.FromArgb(190, 55, 65) };
    public User? AuthenticatedUser { get; private set; }
    public LoginForm(PharmacieStore store)
    {
        this.store = store; Text = "Pharmacie - Connexion"; StartPosition = FormStartPosition.CenterScreen; FormBorderStyle = FormBorderStyle.FixedDialog; MaximizeBox = false; Width = 820; Height = 540; BackColor = Colors.Background;
        var hero = new Panel { Dock = DockStyle.Left, Width = 330, BackColor = Colors.Navy }; hero.Paint += (_, e) => { using var b = new SolidBrush(Color.FromArgb(35, 100, 118)); e.Graphics.FillEllipse(b, 190, -80, 270, 270); using var b2 = new SolidBrush(Color.FromArgb(25, 74, 91)); e.Graphics.FillEllipse(b2, -120, 330, 300, 300); };
        hero.Controls.Add(new Label { Text = "✚", ForeColor = Colors.Teal, Font = new Font("Segoe UI", 52, FontStyle.Bold), AutoSize = true, Location = new Point(42, 48) }); hero.Controls.Add(new Label { Text = "PHARMACIE", ForeColor = Color.White, Font = new Font("Segoe UI", 26, FontStyle.Bold), AutoSize = true, Location = new Point(48, 140) }); hero.Controls.Add(new Label { Text = "Gérez votre officine\navec sérénité.", ForeColor = Color.White, Font = new Font("Segoe UI", 19), AutoSize = true, Location = new Point(50, 205) }); hero.Controls.Add(new Label { Text = "Produits  •  Stock  •  Ventes", ForeColor = Color.FromArgb(186, 216, 224), Font = new Font("Segoe UI", 10), AutoSize = true, Location = new Point(52, 300) }); hero.Controls.Add(new Label { Text = "Solution locale sécurisée", ForeColor = Color.FromArgb(148, 185, 196), Font = new Font("Segoe UI", 9), AutoSize = true, Location = new Point(52, 445) });
        var content = new Panel { Dock = DockStyle.Fill, BackColor = Color.White, Padding = new Padding(58, 55, 58, 40) }; content.Controls.Add(new Label { Text = "Bienvenue", ForeColor = Colors.Navy, Font = new Font("Segoe UI", 24, FontStyle.Bold), AutoSize = true, Location = new Point(58, 48) }); content.Controls.Add(new Label { Text = "Connectez-vous à votre espace de gestion", ForeColor = Colors.Muted, Font = new Font("Segoe UI", 10), AutoSize = true, Location = new Point(61, 91) });
        var form = new TableLayoutPanel { Location = new Point(58, 145), Width = 310, Height = 205, ColumnCount = 1, RowCount = 5 }; form.Controls.Add(FieldLabel("IDENTIFIANT"), 0, 0); StyleField(username); form.Controls.Add(username, 0, 1); form.Controls.Add(FieldLabel("MOT DE PASSE"), 0, 2); StyleField(password); form.Controls.Add(password, 0, 3); var login = PrimaryButton("Se connecter  →", 310); login.Margin = new Padding(0, 14, 0, 0); login.Click += async (_, _) => { message.Text = ""; var user = await this.store.AuthenticateAsync(username.Text, password.Text); if (user is null) { message.Text = "Identifiant ou mot de passe incorrect."; return; } AuthenticatedUser = user; DialogResult = DialogResult.OK; Close(); }; form.Controls.Add(login, 0, 4); content.Controls.Add(form); message.Location = new Point(61, 370); content.Controls.Add(message); content.Controls.Add(new Label { Text = "Première connexion : admin / admin", AutoSize = true, ForeColor = Colors.Muted, Font = new Font("Segoe UI", 9), Location = new Point(61, 412) }); Controls.Add(content); Controls.Add(hero); AcceptButton = login;
    }
    static Label FieldLabel(string text) => new() { Text = text, AutoSize = true, ForeColor = Colors.Muted, Font = new Font("Segoe UI", 8, FontStyle.Bold), Margin = new Padding(0, 4, 0, 0) };
