    static Button PrimaryButton(string text, int width) => new() { Text = text, Width = width, Height = 38, BackColor = Colors.Teal, ForeColor = Color.White, FlatStyle = FlatStyle.Flat, FlatAppearance = { BorderSize = 0 }, Font = new Font("Segoe UI", 10, FontStyle.Bold), Cursor = Cursors.Hand };
}

public sealed class MainForm : Form
{
    readonly PharmacieStore store; readonly User currentUser; readonly TabControl pages = new(); readonly Label pageTitle = new(); readonly Label pageSubtitle = new(); readonly Label status = new(); readonly DataGridView productsGrid = Grid(); readonly DataGridView stockGrid = Grid(); readonly DataGridView cartGrid = Grid(); readonly TextBox search = new() { Width = 280, PlaceholderText = "Rechercher un produit..." }; readonly List<SaleCartLine> cart = []; readonly Label dashboard = new();
    readonly Color activeNav = Color.FromArgb(30, 92, 110);
    public MainForm(PharmacieStore store, User currentUser, string databasePath) { this.store = store; this.currentUser = currentUser; Text = "Pharmacie"; Width = 1280; Height = 800; MinimumSize = new Size(1100, 700); StartPosition = FormStartPosition.CenterScreen; BackColor = Colors.Background; Font = new Font("Segoe UI", 10); }
    protected override async void OnLoad(EventArgs e)
    {
        base.OnLoad(e); pages.Appearance = TabAppearance.FlatButtons; pages.ItemSize = new Size(0, 1); pages.SizeMode = TabSizeMode.Fixed; pages.Dock = DockStyle.Fill; pages.Padding = new Point(0, 0);
        pages.TabPages.Add(BuildDashboard()); pages.TabPages.Add(BuildProducts()); pages.TabPages.Add(BuildStock()); pages.TabPages.Add(BuildSale()); pages.TabPages.Add(BuildSettings());
        var shell = new Panel { Dock = DockStyle.Fill, BackColor = Colors.Background }; shell.Controls.Add(pages); shell.Controls.Add(BuildHeader()); shell.Controls.Add(BuildSidebar()); shell.Controls.Add(BuildStatus()); Controls.Add(shell); Navigate(0, "Tableau de bord", "Vue d'ensemble de votre pharmacie"); await RefreshAll();
    }
    Control BuildSidebar()
    {
        var side = new Panel { Dock = DockStyle.Left, Width = 230, BackColor = Colors.Navy, Padding = new Padding(14, 20, 14, 14) }; side.Controls.Add(new Label { Text = "✚  PHARMACIE", ForeColor = Color.White, Font = new Font("Segoe UI", 17, FontStyle.Bold), AutoSize = true, Location = new Point(18, 22) }); side.Controls.Add(new Label { Text = "GESTION PROFESSIONNELLE", ForeColor = Color.FromArgb(155, 190, 203), Font = new Font("Segoe UI", 8, FontStyle.Bold), AutoSize = true, Location = new Point(21, 55) });
        var nav = new FlowLayoutPanel { Location = new Point(14, 105), Width = 202, Height = 410, FlowDirection = FlowDirection.TopDown, WrapContents = false, BackColor = Color.Transparent }; string[] names = ["Tableau de bord", "Produits", "Stock et lots", "Nouvelle vente", "Paramètres"]; string[] glyphs = ["⌂", "▣", "▤", "€", "⚙"]; for (var i = 0; i < names.Length; i++) { var index = i; var b = NavButton($"  {glyphs[i]}   {names[i]}"); b.Click += (_, _) => Navigate(index, names[index], index == 0 ? "Vue d'ensemble de votre pharmacie" : names[index]); nav.Controls.Add(b); } side.Controls.Add(nav); side.Controls.Add(new Label { Text = "HORS CONNEXION\nBase locale SQLite", ForeColor = Color.FromArgb(150, 182, 193), AutoSize = true, Location = new Point(22, 650), Font = new Font("Segoe UI", 9) }); return side;
    }
    Control BuildHeader() { var h = new Panel { Dock = DockStyle.Top, Height = 92, BackColor = Color.White, Padding = new Padding(30, 18, 30, 12) }; pageTitle.Font = new Font("Segoe UI", 20, FontStyle.Bold); pageTitle.ForeColor = Colors.Navy; pageTitle.AutoSize = true; pageSubtitle.Font = new Font("Segoe UI", 9); pageSubtitle.ForeColor = Colors.Muted; pageSubtitle.AutoSize = true; pageSubtitle.Location = new Point(31, 54); h.Controls.Add(pageTitle); h.Controls.Add(pageSubtitle); var user = new Label { Text = $"{currentUser.NomComplet}\n{currentUser.Role}", AutoSize = true, TextAlign = ContentAlignment.MiddleRight, ForeColor = Colors.Navy, Font = new Font("Segoe UI", 9, FontStyle.Bold), Dock = DockStyle.Right, Padding = new Padding(0, 8, 6, 0) }; h.Controls.Add(user); return h; }
    Control BuildStatus() { status.Dock = DockStyle.Bottom; status.Height = 28; status.Text = "  Prêt"; status.ForeColor = Colors.Muted; status.BackColor = Color.White; status.Padding = new Padding(8, 5, 0, 0); return status; }
    void Navigate(int index, string title, string subtitle) { if (index < pages.TabPages.Count) pages.SelectedIndex = index; pageTitle.Text = title; pageSubtitle.Text = subtitle; }
    TabPage BuildDashboard() { var p = Page(); var wrap = new Panel { Dock = DockStyle.Fill, Padding = new Padding(28) }; dashboard.Dock = DockStyle.Fill; dashboard.TextAlign = ContentAlignment.TopLeft; dashboard.Font = new Font("Segoe UI", 12); dashboard.ForeColor = Colors.Navy; wrap.Controls.Add(dashboard); p.Controls.Add(wrap); return p; }
    TabPage BuildProducts()
    {
        var p = Page(); var top = Toolbar(); top.Controls.Add(search); top.Controls.Add(ActionButton("Rechercher", async (_, _) => await RefreshProducts())); top.Controls.Add(ActionButton("＋ Ajouter un produit", (_, _) => AddProductDialog(), true)); top.Controls.Add(ActionButton("Actualiser", async (_, _) => await RefreshProducts())); search.KeyDown += async (_, e) => { if (e.KeyCode == Keys.Enter) await RefreshProducts(); }; p.Controls.Add(productsGrid); p.Controls.Add(top); productsGrid.CellDoubleClick += (_, _) => AddReceiptFromSelected(); return p;
    }
    TabPage BuildStock() { var p = Page(); var top = Toolbar(); top.Controls.Add(new Label { Text = "Double-cliquez sur un produit pour enregistrer une réception.", AutoSize = true, ForeColor = Colors.Muted, Padding = new Padding(6, 8, 20, 0) }); top.Controls.Add(ActionButton("＋ Nouvelle réception", (_, _) => AddReceiptFromSelected(), true)); p.Controls.Add(stockGrid); p.Controls.Add(top); return p; }
    TabPage BuildSale()
    {
        var p = Page(); var split = new SplitContainer { Dock = DockStyle.Fill, SplitterDistance = 600, Padding = new Padding(20) }; var left = new Panel { Dock = DockStyle.Fill, Padding = new Padding(0, 0, 12, 0) }; var right = new Panel { Dock = DockStyle.Fill, Padding = new Padding(12, 0, 0, 0) }; var find = new TextBox { Dock = DockStyle.Top, Height = 36, PlaceholderText = "Rechercher par nom, référence ou code-barres" }; var catalog = Grid(); left.Controls.Add(catalog); left.Controls.Add(find); split.Panel1.Controls.Add(left); var cartTitle = new Label { Text = "PANIER", Dock = DockStyle.Top, Height = 36, Font = new Font("Segoe UI", 11, FontStyle.Bold), ForeColor = Colors.Navy }; right.Controls.Add(cartGrid); right.Controls.Add(cartTitle); var encaisse = ActionButton("ENCAISSER", async (_, _) => await Checkout(), true); encaisse.Dock = DockStyle.Bottom; encaisse.Height = 44; right.Controls.Add(encaisse); split.Panel2.Controls.Add(right); p.Controls.Add(split);
        async Task LoadCatalog() { catalog.DataSource = (await store.GetProductsAsync(find.Text)).ToList(); if (catalog.Columns.Count > 0) catalog.Columns[0].Visible = false; }
        find.TextChanged += async (_, _) => await LoadCatalog(); catalog.CellDoubleClick += (_, _) => { if (catalog.CurrentRow?.DataBoundItem is ProductRow pr) { var old = cart.FirstOrDefault(x => x.ProductId == pr.Id); if (old is not null) cart[cart.IndexOf(old)] = old with { Quantity = old.Quantity + 1 }; else cart.Add(new SaleCartLine(pr.Id, pr.Designation, 1, pr.SalePrice)); cartGrid.DataSource = null; cartGrid.DataSource = cart.ToList(); } }; p.Enter += async (_, _) => await LoadCatalog(); return p;
    }
    TabPage BuildSettings() { var p = Page(); var panel = new Panel { Dock = DockStyle.Fill, Padding = new Padding(28) }; panel.Controls.Add(new Label { Text = "Configuration et sauvegarde", Font = new Font("Segoe UI", 16, FontStyle.Bold), ForeColor = Colors.Navy, AutoSize = true }); var backup = ActionButton("Créer une sauvegarde", async (_, _) => { using var d = new SaveFileDialog { Filter = "Base SQLite|*.db", FileName = $"pharmacie-{DateTime.Now:yyyyMMdd-HHmm}.db" }; if (d.ShowDialog(this) == DialogResult.OK) { await store.BackupAsync(d.FileName); status.Text = "  Sauvegarde créée."; } }, true); backup.Location = new Point(28, 60); panel.Controls.Add(backup); p.Controls.Add(panel); return p; }
    async Task RefreshAll() { await RefreshProducts(); var stock = await store.GetStockAsync(); stockGrid.DataSource = stock.ToList(); HideColumns(stockGrid, 0, 1); var low = stock.Count(x => x.Quantity <= 0); var exp = stock.Count(x => x.ExpiryDate is not null && x.ExpiryDate <= DateOnly.FromDateTime(DateTime.Today.AddDays(90))); dashboard.Text = $"Bonjour {currentUser.NomComplet},\n\n"; dashboard.Controls.Clear(); dashboard.Controls.Add(DashboardContent(low, exp, stock.Count)); }
    Control DashboardContent(int ruptures, int expiration, int lots) { var panel = new Panel { Dock = DockStyle.Fill }; var welcome = new Label { Text = "Votre activité en un coup d'œil", AutoSize = true, Font = new Font("Segoe UI", 13, FontStyle.Bold), ForeColor = Colors.Navy, Location = new Point(0, 0) }; panel.Controls.Add(welcome); var cards = new FlowLayoutPanel { Location = new Point(0, 48), Width = 900, Height = 125, FlowDirection = FlowDirection.LeftToRight, WrapContents = false }; cards.Controls.Add(Card("LOTS EN STOCK", lots.ToString(), Colors.Teal)); cards.Controls.Add(Card("RUPTURES", ruptures.ToString(), Colors.Red)); cards.Controls.Add(Card("PÉREMPTIONS < 90 J", expiration.ToString(), Colors.Orange)); cards.Controls.Add(Card("STATUT", "Ouvert", Colors.Green)); panel.Controls.Add(cards); panel.Controls.Add(new Label { Text = "Conseil : utilisez l'onglet Vente pour scanner ou rechercher rapidement un produit.", AutoSize = true, ForeColor = Colors.Muted, Location = new Point(0, 205) }); return panel; }
    static Control Card(string title, string value, Color color) { var p = new Panel { Width = 205, Height = 112, BackColor = Color.White, Margin = new Padding(0, 0, 16, 0), Padding = new Padding(16) }; p.Paint += (_, e) => { using var pen = new Pen(Color.FromArgb(225, 230, 235)); e.Graphics.DrawRectangle(pen, 0, 0, p.Width - 1, p.Height - 1); using var brush = new SolidBrush(color); e.Graphics.FillRectangle(brush, 0, 0, 5, p.Height); }; p.Controls.Add(new Label { Text = title, AutoSize = true, ForeColor = Colors.Muted, Font = new Font("Segoe UI", 8, FontStyle.Bold), Location = new Point(18, 18) }); p.Controls.Add(new Label { Text = value, AutoSize = true, ForeColor = color, Font = new Font("Segoe UI", 25, FontStyle.Bold), Location = new Point(16, 42) }); return p; }
    async Task RefreshProducts() { var data = await store.GetProductsAsync(search.Text); productsGrid.DataSource = data.ToList(); HideColumns(productsGrid, 0); status.Text = $"  {data.Count} produit(s) trouvé(s)."; }
    void AddProductDialog() { using var f = new ProductDialog(); if (f.ShowDialog(this) == DialogResult.OK) _ = SaveProduct(f); }
    async Task SaveProduct(ProductDialog f) { try { await store.AddProductAsync(f.ReferenceText, f.DesignationText, f.CategoryText, f.UnitText, f.PriceValue, f.MinimumValue); await RefreshAll(); status.Text = "  Produit enregistré avec succès."; } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Validation", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
    void AddReceiptFromSelected() { if (productsGrid.CurrentRow?.DataBoundItem is not ProductRow product) { MessageBox.Show(this, "Sélectionnez d'abord un produit dans l'onglet Produits."); return; } using var f = new ReceiptDialog(product); if (f.ShowDialog(this) == DialogResult.OK) _ = SaveReceipt(product, f); }
    async Task SaveReceipt(ProductRow product, ReceiptDialog f) { try { await store.AddReceiptAsync(product.Id, f.LotNumberText, f.ExpiryValue, f.QuantityValue, f.CostValue, currentUser); await RefreshAll(); status.Text = "  Réception validée, stock mis à jour."; } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Réception", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
    async Task Checkout() { using var f = new PaymentDialog(cart.Sum(x => x.Quantity * x.UnitPrice)); if (f.ShowDialog(this) != DialogResult.OK) return; try { var result = await store.SellAsync(cart.ToList(), f.ReceivedValue, f.MethodText, currentUser); cart.Clear(); cartGrid.DataSource = null; await RefreshAll(); MessageBox.Show(this, $"Vente {result.Number} enregistrée.\nTotal : {result.Total:C}\nMonnaie : {result.Change:C}", "Vente validée", MessageBoxButtons.OK, MessageBoxIcon.Information); } catch (Exception ex) { MessageBox.Show(this, ex.Message, "Vente", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
    static TabPage Page() => new() { BackColor = Colors.Background, Padding = new Padding(0) };
    static FlowLayoutPanel Toolbar() => new() { Dock = DockStyle.Top, Height = 58, Padding = new Padding(20, 12, 20, 8), BackColor = Color.White, FlowDirection = FlowDirection.LeftToRight, WrapContents = false };
    Button NavButton(string text) => new() { Text = text, Width = 202, Height = 42, TextAlign = ContentAlignment.MiddleLeft, BackColor = Colors.Navy, ForeColor = Color.FromArgb(205, 222, 229), FlatStyle = FlatStyle.Flat, FlatAppearance = { BorderSize = 0 }, Font = new Font("Segoe UI", 10), Cursor = Cursors.Hand, Margin = new Padding(0, 2, 0, 2) };
    static Button ActionButton(string text, EventHandler click, bool primary = false) { var b = new Button { Text = text, AutoSize = true, Height = 34, BackColor = primary ? Colors.Teal : Color.White, ForeColor = primary ? Color.White : Colors.Navy, FlatStyle = FlatStyle.Flat, FlatAppearance = { BorderColor = primary ? Colors.Teal : Color.FromArgb(215, 225, 230), BorderSize = 1 }, Font = new Font("Segoe UI", 9, FontStyle.Bold), Cursor = Cursors.Hand, Padding = new Padding(12, 0, 12, 0) }; b.Click += click; return b; }
    static DataGridView Grid() => new() { Dock = DockStyle.Fill, ReadOnly = true, AutoGenerateColumns = true, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill, SelectionMode = DataGridViewSelectionMode.FullRowSelect, AllowUserToAddRows = false, BackgroundColor = Color.White, BorderStyle = BorderStyle.None, RowHeadersVisible = false, CellBorderStyle = DataGridViewCellBorderStyle.SingleHorizontal, GridColor = Color.FromArgb(232, 237, 240), EnableHeadersVisualStyles = false, ColumnHeadersDefaultCellStyle = new DataGridViewCellStyle { BackColor = Colors.Navy, ForeColor = Color.White, Font = new Font("Segoe UI", 9, FontStyle.Bold), Padding = new Padding(7) }, DefaultCellStyle = new DataGridViewCellStyle { BackColor = Color.White, ForeColor = Colors.Navy, SelectionBackColor = Color.FromArgb(220, 241, 241), SelectionForeColor = Colors.Navy, Padding = new Padding(5) }, RowTemplate = { Height = 34 } };
    static void HideColumns(DataGridView g, params int[] columns) { foreach (var i in columns) if (i < g.Columns.Count) g.Columns[i].Visible = false; }
}

sealed class ProductDialog : Form
{
    readonly TextBox reference = new(); readonly TextBox designation = new(); readonly TextBox category = new() { Text = "Médicaments" }; readonly TextBox unit = new() { Text = "boîte" }; readonly NumericUpDown price = new() { DecimalPlaces = 2, Maximum = 100000 }; readonly NumericUpDown minimum = new() { DecimalPlaces = 2, Maximum = 100000 };
    public string ReferenceText => reference.Text; public string DesignationText => designation.Text; public string CategoryText => category.Text; public string UnitText => unit.Text; public decimal PriceValue => price.Value; public decimal MinimumValue => minimum.Value;
    public ProductDialog() { Text = "Nouveau produit"; Width = 430; Height = 380; StartPosition = FormStartPosition.CenterParent; BackColor = Color.White; var title = new Label { Text = "Ajouter un produit", Font = new Font("Segoe UI", 15, FontStyle.Bold), ForeColor = Color.FromArgb(19, 53, 72), AutoSize = true, Location = new Point(22, 18) }; var t = new TableLayoutPanel { Location = new Point(20, 58), Width = 370, Height = 230, ColumnCount = 2, RowCount = 6, Padding = new Padding(0, 5, 0, 5) }; string[] labels = ["Référence", "Désignation", "Catégorie", "Unité", "Prix de vente", "Seuil minimum"]; Control[] controls = [reference, designation, category, unit, price, minimum]; for (var i = 0; i < labels.Length; i++) { t.Controls.Add(new Label { Text = labels[i], AutoSize = true, Padding = new Padding(0, 7, 0, 0) }, 0, i); controls[i].Dock = DockStyle.Fill; t.Controls.Add(controls[i], 1, i); } var ok = new Button { Text = "Enregistrer", DialogResult = DialogResult.OK, Width = 130, Height = 36, BackColor = Color.FromArgb(24, 135, 139), ForeColor = Color.White, FlatStyle = FlatStyle.Flat, Location = new Point(260, 305) }; Controls.Add(title); Controls.Add(t); Controls.Add(ok); AcceptButton = ok; }
}
sealed class ReceiptDialog : Form
{
    readonly TextBox lot = new(); readonly DateTimePicker expiry = new() { Format = DateTimePickerFormat.Short, ShowCheckBox = true, Value = DateTime.Today.AddYears(1) }; readonly NumericUpDown quantity = new() { DecimalPlaces = 2, Minimum = 0.01m, Maximum = 100000, Value = 1 }; readonly NumericUpDown cost = new() { DecimalPlaces = 2, Maximum = 100000 };
    public string LotNumberText => lot.Text; public DateOnly? ExpiryValue => expiry.Checked ? DateOnly.FromDateTime(expiry.Value) : null; public decimal QuantityValue => quantity.Value; public decimal CostValue => cost.Value;
    public ReceiptDialog(ProductRow p) { Text = "Réception - " + p.Designation; Width = 430; Height = 330; StartPosition = FormStartPosition.CenterParent; BackColor = Color.White; var t = new TableLayoutPanel { Location = new Point(20, 20), Width = 370, Height = 220, ColumnCount = 2, RowCount = 5 }; string[] labels = ["Produit", "N° de lot", "Péremption", "Quantité", "Coût d'achat"]; Control[] controls = [new Label { Text = p.Designation }, lot, expiry, quantity, cost]; for (var i = 0; i < labels.Length; i++) { t.Controls.Add(new Label { Text = labels[i], AutoSize = true, Padding = new Padding(0, 7, 0, 0) }, 0, i); controls[i].Dock = DockStyle.Fill; t.Controls.Add(controls[i], 1, i); } var ok = new Button { Text = "Valider la réception", DialogResult = DialogResult.OK, Width = 160, Height = 36, BackColor = Color.FromArgb(24, 135, 139), ForeColor = Color.White, FlatStyle = FlatStyle.Flat, Location = new Point(230, 255) }; Controls.Add(t); Controls.Add(ok); AcceptButton = ok; }
}
sealed class PaymentDialog : Form
{
    readonly NumericUpDown received = new() { DecimalPlaces = 2, Maximum = 100000 }; readonly ComboBox method = new() { DropDownStyle = ComboBoxStyle.DropDownList };
